"use client";
import Link from "next/link";import {useState} from "react";import {Menu,X,Sparkles} from "lucide-react";import {AnimatePresence,motion} from "motion/react";
const links=[["Services","/services"],["Industries","/industries"],["Portfolio","/portfolio"],["Pricing","/pricing"],["About","/about"],["Resources","/resources"],["Contact","/contact"]];
export default function Header(){const [open,setOpen]=useState(false);return <><div style={{background:"#0b1f3a",color:"white",textAlign:"center",padding:".55rem",fontSize:14}}>Free digital-presence consultation for local businesses</div><header style={{position:"sticky",top:0,zIndex:50,background:"rgba(255,255,255,.94)",backdropFilter:"blur(12px)",borderBottom:"1px solid #e2e8f0"}}><div className="container" style={{height:74,display:"flex",alignItems:"center",justifyContent:"space-between"}}><Link href="/" style={{display:"flex",alignItems:"center",gap:10,fontWeight:900,color:"#0b1f3a"}}><span style={{width:36,height:36,borderRadius:11,display:"grid",placeItems:"center",background:"linear-gradient(135deg,#2457ff,#0f9d8a)",color:"white"}}><Sparkles size={19}/></span>Digital Growth Studio</Link><nav className="desktop-nav" style={{display:"flex",alignItems:"center",gap:22}}>{links.map(([l,h])=><Link className="navlink" key={h} href={h}>{l}</Link>)}<Link className="btn btn-primary" href="/consultation">Book a Free Consultation</Link></nav><button className="mobile-toggle" onClick={()=>setOpen(!open)} aria-expanded={open} aria-label="Toggle navigation" style={{display:"none",background:"white",border:"1px solid #cbd5e1",borderRadius:10,padding:8}}>{open?<X/>:<Menu/>}</button></div><AnimatePresence>{open&&<motion.nav initial={{opacity:0,height:0}} animate={{opacity:1,height:"auto"}} exit={{opacity:0,height:0}} style={{overflow:"hidden",borderTop:"1px solid #e2e8f0",background:"white"}}><div className="container" style={{display:"grid",gap:14,padding:"1rem 0 1.5rem"}}>{links.map(([l,h])=><Link onClick={()=>setOpen(false)} className="navlink" key={h} href={h}>{l}</Link>)}<Link onClick={()=>setOpen(false)} className="btn btn-primary" href="/consultation">Book a Free Consultation</Link></div></motion.nav>}</AnimatePresence></header></>}
