"use client";import {useState} from "react";
export default function NewsletterForm(){const [done,setDone]=useState(false);return <form onSubmit={e=>{e.preventDefault();setDone(true)}} style={{display:"flex",gap:8,flexWrap:"wrap"}}><label className="sr-only" htmlFor="newsletter">Email</label><input id="newsletter" required type="email" placeholder="Email for practical tips" style={{padding:12,borderRadius:10,border:"1px solid #334155",background:"#0f2748",color:"white",flex:1}}/><button className="btn btn-primary" type="submit">{done?"Subscribed":"Subscribe"}</button></form>}
